import assert from 'node:assert/strict';import {writeFileSync} from 'node:fs';
import {blankModel,createProvider,createAccount,createPosition,escapeHTML,money,valueEUR} from '../src/model.js';
import {positionDetailMarkup} from '../src/position-detail-ui.js';import {availablePositionPeriods} from '../src/position-history.js';import {priceQuality} from '../src/quote-quality.js';
const m=blankModel();m.settings.autoRefresh=false;m.providers.push(createProvider({id:'p',name:'SYNTHETIC text audit'}));m.accounts.push(createAccount({id:'a',providerId:'p',name:'SYNTHETIC account',type:'securities'},m));
const p=createPosition({id:'asset',providerId:'p',accountId:'a',name:'SYNTHETIC BTC',kind:'crypto',symbol:'BTC',coinId:'bitcoin',quantity:1},m);m.positions.push(p);
const render=()=>positionDetailMarkup(p,m,{esc:escapeHTML,money,quant:String,valueEUR});
const before=JSON.stringify(m),missing=render();assert.equal(priceQuality(p).state,'missing');const missingPrice=missing.match(/<span>Kurs je Einheit<\/span><strong>([^<]+)<\/strong>/)?.[1];assert.match(missingPrice,/0,00/);assert.match(missing,/Kursquelle: Manuell/);assert.equal(JSON.stringify(m),before);
const report={displayedUnknownPrice:missingPrice,scope:'Pure UI renderer probes on unchanged position-detail source; synthetic only, no network or storage',checks:[{id:'UI-TEXT01',status:'REPRODUCED / P1 OPEN',evidence:'Valid canonical position with no supplied price has quality=missing, yet detail shows0,00 and fallback Manuell. Renderer leaves model unchanged.'}]};
m.priceHistories[p.id]={source:'CSV (selbst geprüft)',currency:'EUR',points:Array.from({length:10},(_,i)=>({date:(2017+i)+'-01-01',total:100+i}))};
const complete=JSON.stringify(m),periods=availablePositionPeriods(p,m),html=render(),visible=[...html.matchAll(/data-position-range="([^"]+)"/g)].map(x=>x[1]);
report.checks.push({id:'UI-TEXT02',status:periods.includes(1096)&&!visible.includes('1096')?'REPRODUCED / OPEN':'FURTHER_REVIEW',available:periods,rendered:visible});
assert.equal((html.match(/data-action="import-price-history"/g)||[]).length,0);assert.equal((html.match(/CSV-Kursverlauf importieren/g)||[]).length,0);
report.checks.push({id:'UI-TEXT03',status:'VISIBLE_UNSUPPORTED_CSV_NOT_REPRODUCED / PREPARED_MARKUP_REVIEW_OPEN',evidence:'Crypto detail currently hides security-only additional tools even with imported history. Keep this guard when removing TradingView; do not expose unsupported crypto import merely by moving prepared markup.'});const supported=positionDetailMarkup({...p,kind:'etf',symbol:'SYNSEC'},m,{esc:escapeHTML,money,quant:String,valueEUR});assert.equal((supported.match(/data-action="import-price-history"/g)||[]).length,1,'supported security control is reachable');const securityPeriods=availablePositionPeriods({...p,kind:'etf',symbol:'SYNSEC'},m);assert.ok(securityPeriods.includes(1096));assert.equal((supported.match(/data-position-range="1096"/g)||[]).length,0);report.securityThreeYearControl={available:securityPeriods,rendered1096:false,supportedCSV:true};report.supportedSecurityControl=true;assert.equal(JSON.stringify(m),complete);report.modelUnchanged=true;writeFileSync('artifacts/text-audit-probes.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));
